code='''from collections import Counter


def _runs(values, color):
    out = []
    start = None
    for i, value in enumerate(values + [None]):
        if value == color and start is None:
            start = i
        elif value != color and start is not None:
            out.append((start, i - 1))
            start = None
    return out


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    edge_values = (grid[0] + grid[-1] + [grid[r][0] for r in range(h)] +
                   [grid[r][-1] for r in range(h)])
    edge_counts = Counter(v for v in edge_values if v != background)
    frame = edge_counts.most_common(1)[0][0]
    target = next(v for v in counts if v != background and v != frame)

    left_runs = _runs([grid[r][0] for r in range(h)], frame)
    right_runs = _runs([grid[r][-1] for r in range(h)], frame)
    top_runs = _runs(grid[0], frame)
    bottom_runs = _runs(grid[-1], frame)

    vertical = [(a, b) for a in left_runs for b in right_runs
                if a[1] - a[0] == b[1] - b[0]]
    horizontal = [(a, b) for a in top_runs for b in bottom_runs
                  if a[1] - a[0] == b[1] - b[0]]
    out = [row[:] for row in grid]

    if vertical:
        left, right = max(vertical, key=lambda pair: pair[0][1] - pair[0][0])
        for r in range(h):
            for c in range(w):
                if grid[r][c] != target:
                    continue
                if left[0] <= r <= left[1]:
                    side = 0
                    mate = right[0] + (r - left[0])
                elif right[0] <= r <= right[1]:
                    side = w - 1
                    mate = left[0] + (r - right[0])
                else:
                    continue
                out[r][c] = 4
                step = 1 if side == 0 else -1
                x = c + step
                while 0 <= x < w and x != side:
                    if out[r][x] != 4 and out[r][x] != frame:
                        out[r][x] = target
                    x += step
                for x in range(w):
                    if out[mate][x] != frame and out[mate][x] != 4:
                        out[mate][x] = target
    elif horizontal:
        top, bottom = max(horizontal, key=lambda pair: pair[0][1] - pair[0][0])
        for r in range(h):
            for c in range(w):
                if grid[r][c] != target:
                    continue
                if top[0] <= c <= top[1]:
                    side = 0
                    mate = bottom[0] + (c - top[0])
                elif bottom[0] <= c <= bottom[1]:
                    side = h - 1
                    mate = top[0] + (c - bottom[0])
                else:
                    continue
                out[r][c] = 4
                step = 1 if side == 0 else -1
                y = r + step
                while 0 <= y < h and y != side:
                    if out[y][c] != 4 and out[y][c] != frame:
                        out[y][c] = target
                    y += step
                for y in range(h):
                    if out[y][mate] != frame and out[y][mate] != 4:
                        out[y][mate] = target
    return out
'''
